function StatusBadge({ label, tone = 'slate' }: { label: string; tone?: string }) {
  return <span className={`review-badge review-badge-${tone}`}>{label}</span>;
}

function Metric({ label, value, note, icon: Icon, tone = 'green' }: { label: string; value: string; note: string; icon: LucideIcon; tone?: string }) {
  return <section className="review-metric"><div className={`review-metric-icon tone-${tone}`}><Icon size={17} /></div><p className="review-muted">{label}</p><div className="review-metric-value">{value}</div><p className="review-footnote">{note}</p></section>;
}

function SectionCard({ title, action, children }: { title: string; action?: string; children: React.ReactNode }) {
  return <section className="review-card"><div className="review-card-heading"><h3>{title}</h3>{action && <button className="review-link-button" type="button">{action}<ArrowRight size={14} /></button>}</div>{children}</section>;
}

function TableFrame({ headers, children }: { headers: string[]; children: React.ReactNode }) {
  return <div className="review-table-scroll"><table className="review-table"><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>;
}

function StatePreview({ state }: { state: ReviewState }) {
  const messages: Record<Exclude<ReviewState, 'populated'>, { title: string; body: string; button: string }> = {
    loading: { title: 'Se încarcă datele', body: 'Indicatorii și listele de lucru se pregătesc pentru această vizualizare.', button: 'Loading state' },
    empty: { title: 'Nimic aici încă', body: 'Creează primul element pentru a începe să urmărești activitatea.', button: 'Adaugă primul element' },
    'no-results': { title: 'Nu am găsit rezultate', body: 'Încearcă să ajustezi filtrele sau termenul de căutare.', button: 'Resetează filtrele' },
    error: { title: 'Datele nu au putut fi încărcate', body: 'Aceasta este o stare de eroare demonstrativă. Nicio solicitare nu a fost trimisă.', button: 'Încearcă din nou' },
    'permission-denied': { title: 'Nu ai acces la această secțiune', body: 'Exemplu de stare de permisiune: rolul QA/QC poate vedea inspecțiile atribuite, dar nu poate modifica setările proiectului.', button: 'Solicită acces' },
    success: { title: 'Modificările au fost salvate', body: 'Starea de succes este simulată local și nu persistă în backend.', button: 'Continuă' },
    confirmation: { title: 'Confirmă acțiunea', body: 'Ești pe cale să trimiți raportul zilnic spre revizuire.', button: 'Confirmă trimiterea' },
    'destructive-confirmation': { title: 'Arhivezi această înregistrare?', body: 'Acțiunea demonstrativă este reversibilă în prototip. Nicio înregistrare reală nu va fi modificată.', button: 'Arhivează local' },
  };
  if (state === 'populated') return null;
  const content = messages[state];
  return <div className={`review-state-panel state-${state}`}><div className="review-state-icon">{state === 'loading' ? <span className="review-spinner" /> : state === 'error' ? <AlertCircle size={21} /> : state === 'permission-denied' ? <ShieldAlert size={21} /> : state === 'success' ? <CheckCircle2 size={21} /> : state.includes('confirmation') ? <AlertTriangle size={21} /> : <FileText size={21} />}</div><h3>{content.title}</h3><p>{content.body}</p><button className="review-button review-button-primary" type="button">{content.button}</button>{state === 'success' && <span className="review-local-note"><Check size={13} /> Prototype — local only</span>}</div>;
}

